import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# --------------------- CUDA extension ---------------------
_ext_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void sum_reduce_kernel(const scalar_t* __restrict__ in,
                                  scalar_t* __restrict__ out,
                                  int64_t reduce,
                                  int64_t stride_reduce,
                                  int64_t inner,
                                  int64_t stride_outer) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = stride_outer;               // total output elements = outer * inner
    if (idx >= total) return;

    int64_t outer_idx = idx / inner;
    int64_t inner_idx = idx % inner;
    int64_t base = outer_idx * stride_outer + inner_idx;   // start offset for this output element

    float sum = 0.0f;
    #pragma unroll 4
    for (int64_t k = 0; k < reduce; ++k) {
        sum += __half2float(in[base + k * stride_reduce]);
    }
    out[idx] = __float2half(sum);
}

void sum_reduce_launcher(at::Tensor input,
                         at::Tensor output,
                         int64_t dim) {
    const int64_t reduce = input.size(dim);

    // compute outer (product of dims before `dim`) and inner (product after)
    int64_t outer = 1;
    for (int64_t i = 0; i < dim; ++i) outer *= input.size(i);
    int64_t inner = 1;
    for (int64_t i = dim + 1; i < input.dim(); ++i) inner *= input.size(i);

    const int64_t stride_reduce = inner;           // distance between consecutive elements in the reduced dimension
    const int64_t stride_outer = reduce * inner;   // distance between consecutive outer blocks

    const int threads = 256;
    const int blocks = static_cast<int>((outer * inner + threads - 1) / threads);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "sum_reduce_cuda", ([&] {
        sum_reduce_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            reduce,
            stride_reduce,
            inner,
            stride_outer);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}

at::Tensor sum_reduce(at::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "sum_reduce: input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::ScalarType::Half,
                "sum_reduce: input must be of type torch.float16");

    // Ensure contiguous layout for simple stride calculations
    input = input.contiguous();

    // Prepare output shape (same as input but reduced dim = 1)
    std::vector<int64_t> out_sizes = input.sizes().vec();
    out_sizes[dim] = 1;
    auto output = at::empty(out_sizes, input.options());

    sum_reduce_launcher(input, output, dim);
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("sum_reduce", &sum_reduce, "Sum reduction over a dimension (float16)");
}
'''

# Compile the extension
_sum_reduce_ext = load_inline(name='sum_reduce_ext',
                              cpp_sources=_ext_source,
                              functions=['sum_reduce'],
                              verbose=False)

# --------------------- Model definition ---------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model, using a custom CUDA kernel.
    Performs sum reduction over the specified dimension while keeping the dimension.
    All tensors are float16.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Convert to FP16 if not already, keep on the same device
        x_fp16 = x.to(dtype=torch.float16, device=x.device)
        return _sum_reduce_ext.sum_reduce(x_fp16, self.dim)

# --------------------- Helper functions (mirroring reference) ---------------------
def get_inputs():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2, device='cuda')
    return [x]

def get_init_inputs():
    reduce_dim = 1
    return [reduce_dim]

# Export symbols
__all__ = ['ModelNew', 'get_inputs', 'get_init_inputs']
